class Calculator {
    int add(int a, int b){
        return a + b;
    }

    int add(int a, int b, int c){
        return a + b + c;
    }

    double add(double a, double b){
        return a + b;
    }
}

class Animal {
    void sound(){
        System.out.println("Animal Sound");
    }
}

class Dog extends Animal {
    @Override
    void sound(){
        System.out.println("Dog Barks");
    }
}

Animal obj = new Dog();
obj.sound();
// Output: Dog Barks
